 void login(){if(authBusy)return;LinearLayout form=column();form.setPadding(dp(20),dp(8),dp(20),0);EditText email=input(form,"Email",InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_EMAIL_ADDRESS),password=input(form,"Пароль",InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);
  AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Вход в CELIKOM").setView(form).setNegativeButton("Отмена",(d,w)->pendingStart=false).setPositiveButton("Войти",null).create();dialog.setOnCancelListener(d->pendingStart=false);
  dialog.setOnShowListener(d->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{String address=email.getText().toString().trim(),pass=password.getText().toString();if(address.isEmpty()||address.length()>254||pass.isEmpty()||pass.length()>128){toast("Введите email и пароль");return;}authBusy=true;password.setText("");dialog.dismiss();serverStatus="Выполняется вход…";api().login(address,pass,(j,error)->{authBusy=false;if(error!=null){pendingStart=false;serverStatus=error(error);if(visible())toast(serverStatus);return;}if(j.optBoolean("verification_required")){serverStatus="Подтвердите email кодом из письма";if(visible())verify(address);else pendingStart=false;}else{serverStatus="";resetLookup();if(pendingStart&&visible())begin();checkServer();}});}));dialog.show();}
 void verify(String address){LinearLayout form=column();form.setPadding(dp(20),dp(8),dp(20),0);EditText code=input(form,"Код из письма",InputType.TYPE_CLASS_NUMBER);code.setFilters(new InputFilter[]{new InputFilter.LengthFilter(6)});AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Подтвердить email").setView(form).setNegativeButton("Отмена",(d,w)->pendingStart=false).setPositiveButton("Подтвердить",null).create();dialog.setOnCancelListener(d->pendingStart=false);dialog.setOnShowListener(d->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{String value=code.getText().toString();if(!value.matches("[0-9]{6}")||authBusy)return;authBusy=true;dialog.getButton(AlertDialog.BUTTON_POSITIVE).setEnabled(false);api().verify(address,value,(j,error)->{authBusy=false;if(!visible())return;if(error!=null){serverStatus=error(error);toast(serverStatus);dialog.getButton(AlertDialog.BUTTON_POSITIVE).setEnabled(true);return;}dialog.dismiss();serverStatus="";resetLookup();if(pendingStart)begin();checkServer();});}));dialog.show();}
 void resetLookup(){uiAccountGeneration=api().accountGeneration;accountAccess=null;uiProblem="";ProbeService p=ProbeService.instance;if(p!=null&&p.replacement!=null){p.replacement.lookupKey=null;p.replacement.descriptor=null;}presenceChecked=0;presenceStatus="";}
 void checkServer(){if(accessBusy)return;accessBusy=true;long account=api().accountGeneration;api().check((j,error)->{accessBusy=false;if(account!=api().accountGeneration)return;if(error!=null){serverStatus=error(error);return;}accountAccess=j.optJSONObject("entitlement");serverStatus="";});}
 void logout(){if(authBusy)return;stop();authBusy=true;api().logout((j,error)->{authBusy=false;serverStatus="";accountAccess=null;presenceStatus="";if(visible()){render();toast(error==null?"Вы вышли из аккаунта на этом устройстве":"Локальный выход выполнен. Сервер недоступен.");}});}
 String error(String code){switch(code){case "track_pending":return "Версия этой песни уже на проверке";case "track_already_approved":case "already_approved":return "Версия этой песни уже есть в CELIKOM";case "duration_mismatch":return "Длительность файла отличается от песни";case "invalid_mp3":case "invalid_m4a":case "invalid_audio_file":return "Выберите корректный MP3 или M4A до 30 МБ";case "uploads_disabled":return "Приём версий временно недоступен";case "invalid_message":case "message_required":return "Введите сообщение от 3 до 2000 символов";case "upload_interrupted":return "Загрузка прервана. Можно повторить отправку.";case "login_required":case "invalid_session":case "access_denied":case "trial_not_activated":case "invalid_credentials":case "rate_limited":return ReplacementEngine.message(code);default:return "Не удалось связаться с CELIKOM. Попробуйте ещё раз.";}}
 void contributionCheck(MobileActions.Target t,Runnable proceed){if(contributionBusy)return;contributionBusy=true;long account=api().accountGeneration;api().presence(t.id,(j,error)->{contributionBusy=false;if(!visible())return;if(!current(t)||account!=api().accountGeneration){toast("Песня или аккаунт изменились. Попробуйте снова.");return;}if(error!=null){toast(error(error));return;}String state=j.optString("status");if(!"none".equals(state)){toast("pending".equals(state)?"Версия этой песни уже на проверке":"approved".equals(state)?"Версия этой песни уже есть в CELIKOM":"Не удалось проверить наличие версии");return;}proceed.run();});}
