 void stage(Uri uri,MobileActions.Target t){if(t==null||!current(t)){toast("Песня изменилась. Выберите файл заново.");return;}toast("Подготавливаем файл…");final long account=api().accountGeneration;files.execute(()->{File staged=null;String extension=null,fail=null;try{String name="";try(Cursor cursor=getContentResolver().query(uri,new String[]{OpenableColumns.DISPLAY_NAME,OpenableColumns.SIZE},null,null,null)){if(cursor!=null&&cursor.moveToFirst()){name=cursor.getString(0);if(!cursor.isNull(1)&&cursor.getLong(1)>MobileActions.MAX_AUDIO_BYTES)throw new Exception("invalid_audio_file");}}extension=MobileActions.extension(name);staged=File.createTempFile("contribution-","."+extension,getCacheDir());try(InputStream in=getContentResolver().openInputStream(uri);OutputStream out=new FileOutputStream(staged)){if(in==null)throw new IOException();byte[] b=new byte[32768];int n;long total=0;while((n=in.read(b))!=-1){if((total+=n)>MobileActions.MAX_AUDIO_BYTES)throw new Exception("invalid_audio_file");out.write(b,0,n);}if(total<1024)throw new Exception("invalid_audio_file");}}catch(Exception e){if(staged!=null)staged.delete();staged=null;fail="invalid_audio_file";}final File file=staged;final String ext=extension,error=fail;handler.post(()->{if(file==null){if(visible())toast(error(error));return;}if(!visible()||!current(t)||account!=api().accountGeneration){file.delete();if(visible())toast("Песня или аккаунт изменились. Выберите файл заново.");return;}showUpload(t,file,ext,account);});});}
 void showUpload(MobileActions.Target t,File file,String ext,long account){LinearLayout form=column();form.setPadding(dp(20),dp(8),dp(20),0);label(form,t.artist+" — "+t.title,16,FG);label(form,"Версия появится после проверки. MP3 или M4A, до 30 МБ.",13,MUTED);CheckBox rights=new CheckBox(this);rights.setText("У меня есть права на загрузку этой версии");rights.setTextColor(FG);form.addView(rights);TextView note=label(form,"",13,MUTED);String request=UUID.randomUUID().toString();boolean[] busy={false};uploadDialog=new AlertDialog.Builder(this).setTitle("Загрузить версию").setView(form).setNegativeButton("Отмена",null).setPositiveButton("Отправить",null).create();AlertDialog dialog=uploadDialog;
  dialog.setOnDismissListener(d->{if(!busy[0])file.delete();if(uploadDialog==dialog)uploadDialog=null;});dialog.setOnShowListener(d->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{if(busy[0])return;if(!rights.isChecked()){set(note,"Подтвердите право на загрузку");return;}if(!current(t)||account!=api().accountGeneration){set(note,"Песня или аккаунт изменились. Откройте загрузку заново.");return;}busy[0]=true;rights.setEnabled(false);dialog.setCancelable(false);dialog.getButton(AlertDialog.BUTTON_NEGATIVE).setEnabled(false);dialog.getButton(AlertDialog.BUTTON_POSITIVE).setEnabled(false);contributionBusy=true;set(note,"Отправляем…");api().contribute(t,file,ext,request,percent->{if(visible())set(note,"Загрузка: "+percent+" %");},(j,error)->{busy[0]=false;contributionBusy=false;if(!visible()){file.delete();return;}dialog.setCancelable(true);dialog.getButton(AlertDialog.BUTTON_NEGATIVE).setEnabled(true);dialog.getButton(AlertDialog.BUTTON_POSITIVE).setEnabled(true);rights.setEnabled(true);if(error==null){presenceChecked=0;dialog.dismiss();toast("Версия отправлена на проверку");}else set(note,error(error));});}));dialog.show();}
 void suggest(){MobileActions.Target t=target();if(t!=null)contributionCheck(t,()->showSuggestion(t));}
 void showSuggestion(MobileActions.Target t){long account=api().accountGeneration;new AlertDialog.Builder(this).setTitle("Предложить песню?").setMessage(t.artist+" — "+t.title).setNegativeButton("Отмена",null).setPositiveButton("Отправить",(d,w)->{if(!current(t)||account!=api().accountGeneration){toast("Песня или аккаунт изменились. Попробуйте снова.");return;}contributionBusy=true;suggestButton.setEnabled(false);api().contribute(t,null,null,null,percent->{},(j,error)->{contributionBusy=false;if(visible())toast(error!=null?error(error):"rejected".equals(j.optString("status"))?"Предложение этой песни ранее отклонено":"reviewed".equals(j.optString("status"))?"Предложение этой песни уже рассмотрено":"Песня предложена");});}).show();}
 void support(LinearLayout form){Spinner kind=new Spinner(this);kind.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Обычное обращение","Проблема с текущей песней"}));form.addView(kind);Spinner category=new Spinner(this);category.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Не включается версия CELIKOM","Играет неправильная версия","Звук обрывается или рассинхронизируется","Другая проблема"}));form.addView(category);category.setVisibility(View.GONE);TextView song=label(form,"",13,MUTED);song.setVisibility(View.GONE);EditText message=input(form,"Опишите проблему",InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_MULTI_LINE);message.setSingleLine(false);message.setMinLines(3);message.setFilters(new InputFilter[]{new InputFilter.LengthFilter(2000)});TextView note=label(form,"",13,MUTED);MobileActions.Target[] pinned={null};JSONObject[] pending={null};String[] previous={""},key={UUID.randomUUID().toString()};long[] account={-1};
  kind.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> a){}public void onItemSelected(AdapterView<?> a,View v,int position,long id){pinned[0]=position==1?target():null;category.setVisibility(position==1?View.VISIBLE:View.GONE);song.setVisibility(position==1?View.VISIBLE:View.GONE);set(song,pinned[0]==null?"Сначала включите песню в Яндекс Музыке":pinned[0].artist+" — "+pinned[0].title);message.setHint(position==1?"Комментарий (необязательно)":"Опишите проблему");}});
  Button send=button(form,"Отправить",()->{},false);send.setOnClickListener(v->{if(!api().signedIn()){toast("Войдите в аккаунт CELIKOM");return;}boolean isSong=kind.getSelectedItemPosition()==1;MobileActions.Target t=isSong?pinned[0]:null;try{if(isSong&&(t==null||!current(t)))throw new Exception("track_required");String text=message.getText().toString(),fingerprint=kind.getSelectedItemPosition()+"|"+category.getSelectedItemPosition()+"|"+text+"|"+(t==null?"":t.key);if(!fingerprint.equals(previous[0])||account[0]!=api().accountGeneration){key[0]=UUID.randomUUID().toString();pending[0]=null;previous[0]=fingerprint;account[0]=api().accountGeneration;}if(pending[0]==null)pending[0]=MobileActions.support(text,key[0],t,new String[]{"not_replacing","wrong_version","audio_issue","other"}[category.getSelectedItemPosition()]);send.setEnabled(false);message.setEnabled(false);kind.setEnabled(false);category.setEnabled(false);set(note,"Отправляем…");api().support(pending[0],(j,error)->{if(!visible())return;send.setEnabled(true);message.setEnabled(true);kind.setEnabled(true);category.setEnabled(true);set(note,error==null?"Сообщение отправлено":error(error));if(error==null){message.setText("");previous[0]="";pending[0]=null;}});}catch(Exception e){set(note,"track_required".equals(e.getMessage())?"Песня изменилась. Выберите вид обращения заново.":error(e.getMessage()));}});}
 void export(){if(exportBusy)return;if(!LogStore.hasReport()){toast("Диагностика пока пуста. Сначала нажмите «Старт».");return;}exportBusy=true;files.execute(()->{File snapshot=null;try{snapshot=File.createTempFile("diagnostics-",".txt",getCacheDir());LogStore.snapshot(snapshot);}catch(Exception e){if(snapshot!=null)snapshot.delete();snapshot=null;}final File result=snapshot;handler.post(()->{if(!visible()||result==null){if(result!=null)result.delete();exportBusy=false;if(visible())toast("Не удалось подготовить диагностику");return;}exportSnapshot=result;try{startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("text/plain").putExtra(Intent.EXTRA_TITLE,"CELIKOM-combined-"+new SimpleDateFormat("yyyyMMdd-HHmmss",Locale.ROOT).format(new Date())+".txt"),20);}catch(RuntimeException e){result.delete();exportSnapshot=null;exportBusy=false;toast("Не удалось открыть сохранение TXT");}});});}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==30){MobileActions.Target t=pickerTarget;pickerTarget=null;if(result==RESULT_OK&&data!=null&&data.getData()!=null)stage(data.getData(),t);return;}if(request!=20)return;File snapshot=exportSnapshot;exportSnapshot=null;exportBusy=false;if(snapshot==null)return;if(result!=RESULT_OK||data==null||data.getData()==null){snapshot.delete();return;}Uri uri=data.getData();files.execute(()->{boolean ok=false;try(OutputStream out=getContentResolver().openOutputStream(uri,"wt")){if(out==null)throw new IOException();DiagnosticJournal.copy(snapshot,out);ok=true;}catch(Exception ignored){}finally{snapshot.delete();}final boolean success=ok;handler.post(()->{if(visible())set(reportNote,success?"Диагностика сохранена":"Не удалось сохранить диагностику");});});}
 @Override protected void onNewIntent(Intent i){super.onNewIntent(i);setIntent(i);receive(i);}
 void receive(Intent i){
  if(i==null)return;
  if(NotificationTarget.ACTION.equals(i.getAction())){
   setIntent(new Intent(this,RecorderActivity.class));
   NotificationTarget requested=new NotificationTarget(i.getStringExtra("notification_run"),i.getStringExtra("notification_track"),i.getStringExtra("notification_key"),i.getLongExtra("notification_account",-1));ProbeService p=ProbeService.instance;MobileActions.Target t=target();
   if(p==null||t==null||!requested.matches(p.notificationRun,t.id,t.key,api().accountGeneration)){toast("Песня или подключение уже изменились. Выберите текущую песню в CELIKOM.");return;}
   contributionCheck(t,()->showSuggestion(t));return;
  }
  if(!Intent.ACTION_SEND.equals(i.getAction()))return;CharSequence value=i.getCharSequenceExtra(Intent.EXTRA_TEXT);List<Object> links=ShareLinks.parse(value==null?"":value.toString());ProbeService p=ProbeService.instance;if(p!=null&&p.alive()&&!links.isEmpty()){LogStore.log("share_reference",LogStore.map("links",links));if(p.albumProbe!=null)p.albumProbe.reference(links);toast("Ссылка добавлена в диагностику");}setIntent(new Intent(this,RecorderActivity.class));
 }
 void enableNotifications(){
  if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED&&!shouldShowRequestPermissionRationale(Manifest.permission.POST_NOTIFICATIONS)&&!getPreferences(0).getBoolean("notificationAsked",false)){getPreferences(0).edit().putBoolean("notificationAsked",true).apply();requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},11);return;}
  try{startActivity(new Intent(android.provider.Settings.ACTION_APP_NOTIFICATION_SETTINGS).putExtra(android.provider.Settings.EXTRA_APP_PACKAGE,getPackageName()));}catch(RuntimeException e){toast("Откройте настройки уведомлений CELIKOM в настройках Android.");}
 }

 void toast(String text){Toast.makeText(this,text,Toast.LENGTH_LONG).show();}
 @Override protected void onSaveInstanceState(Bundle out){super.onSaveInstanceState(out);if(pickerTarget!=null){out.putString("pickerId",pickerTarget.id);out.putString("pickerKey",pickerTarget.key);out.putString("pickerTitle",pickerTarget.title);out.putString("pickerArtist",pickerTarget.artist);out.putLong("pickerDuration",pickerTarget.duration);}if(exportSnapshot!=null)out.putString("reportSnapshot",exportSnapshot.getPath());}
 @Override protected void onDestroy(){startIntent.cancel();pendingStart=false;handler.removeCallbacksAndMessages(null);if(uploadDialog!=null)uploadDialog.dismiss();if(exportSnapshot!=null&&isFinishing())exportSnapshot.delete();files.shutdown();super.onDestroy();}
